{
  "title": "Đà Lạt thong thả, sáng vườn chiều phố",
  "summary": "Một ngày chậm rãi ở Đà Lạt: sáng thăm vườn hoa và chợ, trưa ăn bánh căn, chiều ngồi cà phê ngắm phố, tối dùng bữa nhẹ nhàng. Bớt đi bộ, thêm thời gian ngồi xuống tận hưởng.",
  "stops": [
    {
      "poi_id": "p286",
      "kind": "activity",
      "must_do_id": "p286",
      "note": "Vườn hoa buổi sáng mát, đi thong thả không cần vội. Cảnh đẹp cho người thích chụp ảnh."
    },
    {
      "poi_id": "p165",
      "kind": "activity",
      "must_do_id": "p165",
      "note": "Chợ Đà Lạt là nơi thấy nhịp sống địa phương rõ nhất. Đi một vòng, ngửi mùi trái cây và cà phê."
    },
    {
      "poi_id": "p191",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bánh căn nóng hổi, ngồi xuống ăn từ tốn. Đúng kiểu ăn vặt mà no bụng giữa trưa."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Mây Lang Thang cho buổi chiều ngồi cà phê ngắm phố núi. Không cần đi đâu xa, cứ ngồi đây là đủ chậm."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa tối ngồi lại lâu một chút, không gian ấm cúng. Ngày thong thả thì bữa tối cũng nên thong thả."
    }
  ]
}
```

